// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address account, address operator) public {
        // Deploy a fresh C to avoid state pollution from previous calls
        c = new C(address(this), address(this));

        // Ensure account is not the zero address (ERC1155 requires non-zero for isApprovedForAll)
        vm.assume(account != address(0));

        // Call the function that indirectly exercises isApprovedForAll: safeTransferFrom
        // We first mint a token to account so they have balance to transfer
        // c.mint(uint256 tokenId, uint256 quantity) requires item to exist; we create one
        // But creating a game item requires admin; we are admin in setup
        // Actually, adjustAdminAccess is called after setup; we need to set up
        // Simpler: directly test isApprovedForAll by calling it and comparing to a known base

        // The bug changes isApprovedForAll to always return false.
        // A general rule: isApprovedForAll(account, operator) should be false by default
        // because we never set any approval.
        bool expected = false;
        bool actual = c.isApprovedForAll(account, operator);

        // This rule holds on reference (returns false) and breaks on mutant (still false? No, mutant returns false too)
        // Wait: the mutant also returns false, so the bug does not affect false default.
        // The rule must catch when the reference returns true.
        // So we need to set an approval first.

        // Let's use setApprovalForAll to set operator for account.
        // We'll prank as account.
        vm.prank(account);
        c.setApprovalForAll(operator, true);

        // Now reference should return true for that account/operator, mutant returns false.
        // But we must also ensure operator is not the zero address (though not required in ERC1155? Actually _setApprovalForAll requires owner != operator, but we can have operator = account? It will revert if owner==operator. Let's avoid that.)
        vm.assume(operator != account);

        bool expectedApproved = true;
        bool actualApproved = c.isApprovedForAll(account, operator);

        assertTrue(actualApproved == expectedApproved, "isApprovedForAll should return true after setApprovalForAll");
    }
}

